It looks like the directory is empty. I'll create a signup form example with email validation for you. Here's a complete working solution:

**HTML + Vanilla JS:**
```html
<!DOCTYPE html>
<html>
<head>
  <style>
    .error { color: red; font-size: 12px; margin-top: 4px; }
    input.invalid { border-color: red; }
  </style>
</head>
<body>
  <form id="signupForm">
    <input type="email" id="email" name="email" placeholder="Enter your email" required>
    <span class="error" id="emailError"></span>
    <button type="submit">Sign Up</button>
  </form>

  <script>
    const emailInput = document.getElementById('email');
    const emailError = document.getElementById('emailError');
    const form = document.getElementById('signupForm');

    function validateEmail(email) {
      const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return regex.test(email);
    }

    emailInput.addEventListener('blur', () => {
      if (emailInput.value && !validateEmail(emailInput.value)) {
        emailError.textContent = 'Please enter a valid email address';
        emailInput.classList.add('invalid');
      } else {
        emailError.textContent = '';
        emailInput.classList.remove('invalid');
      }
    });

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      if (!validateEmail(emailInput.value)) {
        emailError.textContent = 'Please enter a valid email address';
        emailInput.classList.add('invalid');
        return;
      }
      console.log('Form submitted with email:', emailInput.value);
      // Send to server
    });
  </script>
</body>
</html>
```

**React version:**
```jsx
import { useState } from 'react';

export default function SignupForm() {
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');

  const validateEmail = (value) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  };

  const handleBlur = () => {
    if (email && !validateEmail(email)) {
      setError('Please enter a valid email address');
    } else {
      setError('');
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validateEmail(email)) {
      setError('Please enter a valid email address');
      return;
    }
    console.log('Form submitted:', email);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        onBlur={handleBlur}
        placeholder="Enter your email"
        style={{ borderColor: error ? 'red' : 'initial' }}
      />
      {error && <span style={{ color: 'red', fontSize: '12px' }}>{error}</span>}
      <button type="submit">Sign Up</button>
    </form>
  );
}
```

Both versions validate on blur (when user leaves the field) and on form submit. The regex checks for a basic email format: `text@domain.extension`. If you need stricter validation, let me know and I can adjust it.
